const A='http://localhost:3000/api/v1';
const mode=process.argv[2];
const users=await (await fetch(A+'/users',{headers:{'x-user-id':'x'}})).json();
const hr=users.filter(u=>u.role==='HR'); const emp=users.find(u=>u.role==='EMPLOYEE');
const h={'x-user-id':emp.id,'content-type':'application/json'};
const rooms=await (await fetch(A+'/rooms',{headers:h})).json();
console.log('users',users.length,'HR',hr.length,'rooms',rooms.length);
if(mode==='create'){
  const d=new Date(Date.now()+2*86400000); d.setUTCHours(16,0,0,0); // 10:00 UTC-6
