  const body={roomId:rooms[0].id,title:'T-08 verificación',startsAt:d.toISOString(),endsAt:e.toISOString(),attendees:2};
  let ws; const got=new Promise(r=>{ws=new WebSocket('ws://localhost:3000/ws');ws.onmessage=m=>r(m.data)});
  await new Promise(r=>ws.onopen=r);
  const r1=await fetch(A+'/reservations',{method:'POST',headers:h,body:JSON.stringify(body)});
  console.log('create',r1.status, (await r1.text()).slice(0,120));
  console.log('ws',await Promise.race([got,new Promise(r=>setTimeout(()=>r('TIMEOUT'),3000))])); ws.close();
  const r2=await fetch(A+'/reservations',{method:'POST',headers:h,body:JSON.stringify(body)});
  console.log('conflict',r2.status);
}
const rs=await (await fetch(A+'/reservations',{headers:h})).json();
console.log('reservations',Array.isArray(rs)?rs.length:JSON.stringify(rs).slice(0,100));
EOF
